def solve(nums):
    candidates = [None, None]  # will contain the 2 possible candidates, one entry null when no matryochka found yet
    counts = [0, 0]  # will contain the counts of the 2 possible candidates
    cur = 0  # counter that will replace the candidate in candidates[0] and add one to the counter in counts[0]
    remove = 1  # counter that removes one from the counter in counts[0]
    for num in nums:
        if candidates[remove] == num:
            counts[remove] -= 1
        elif candidates[cur] == num:
            counts[cur] += 1
        else:
            if candidates[cur] == None:
                candidates[cur] = num
                counts[cur] = 1
            else:
                candidates.remove(num)  # just "borrow" some matryokhas from somewhere else
                counts.remove(num)
                counts.append(1)
                candidates.append(num)
        if counts[remove] == 0:
            candidate = candidates.pop(remove)
            counts.remove(candidate)
            remove = (remove + 1) % 2
    res = candidates[cur]
    return res

